import AppKit
import StrandCore

@MainActor enum PresentationChecks {
    static func run() {
        var wired = NetworkInterface(id: "en9")
        wired.hardwareType = "Ethernet"; wired.linkActive = true; wired.displayName = "USB Ethernet"
        precondition(wired.addresses.isEmpty && wired.ethernetCable, "An Ethernet link needs no IP or internet to be shown")
        wired.linkSpeed = 1_000_000_000
        let gigabit = ConnectionItem.ethernet(wired)
        precondition(gigabit.chip == "1 Gbps link" && gigabit.facts?.first == CableFact(name: "Link speed", value: "1 Gbps") && gigabit.details.contains("Link speed: 1 Gbps"), "Ethernet shows its negotiated link speed")
        wired.linkSpeed = 0
        precondition(ConnectionItem.ethernet(wired).chip == "Link active" && ConnectionItem.ethernet(wired).facts?.count == 1, "Unknown link speed is hidden, not guessed")
        precondition(NetworkInterface.speed(2_500_000_000) == "2.5 Gbps" && NetworkInterface.speed(100_000_000) == "100 Mbps")
        print("PASS: Ethernet cable item reports negotiated link speed and hides an unknown one")
        wired.linkActive = false
        precondition(!wired.ethernetCable, "Inactive adapters must not appear as connected cables")
        precondition(ConnectionPhoto.name(kind: "ethernet") == "ethernet" && ConnectionPhoto.name(kind: "ethernet", dark: true) == "ethernet", "One Ethernet photo serves both appearances")
        for speed in [nil, "480 Mbps", "Not reported"] as [String?] {
            precondition(ConnectionPhoto.name(kind: "cable", speed: speed) == "usb-c-light" && ConnectionPhoto.name(kind: "cable", speed: speed, dark: true) == "usb-c-dark")
        }
        for speed in ["5 Gbps", "10 Gbps", "20 Gbps", "USB Gen 2 · 10–20 Gbps", "40 Gbps"] {
            precondition(ConnectionPhoto.name(kind: "cable", speed: speed) == "thunderbolt-4-light" && ConnectionPhoto.name(kind: "cable", speed: speed, dark: true) == "thunderbolt-4-dark")
        }
        precondition(ConnectionPhoto.name(kind: "cable", speed: "USB4 Gen 4 · 80 Gbps", dark: true) == "thunderbolt-5-dark")
        precondition(ConnectionPhoto.name(kind: "magsafe", speed: "40 Gbps") == "magsafe-light" && ConnectionPhoto.name(kind: "magsafe", dark: true) == "magsafe-dark")
        precondition(ConnectionPhoto.name(kind: "charger") == "charger-light" && ConnectionPhoto.name(kind: "charger", dark: true) == "charger-dark")
        precondition(ConnectionPhoto.images.count == 19, "All light, dark and shared photos load")
        print("PASS: light and dark photo routing for ordinary/unknown, 5–40/80 Gbps, MagSafe and chargers; shared Ethernet photo; all bundled photos load")
        precondition(ConnectionPhoto.name(kind: "hdmi") == nil, "HDMI uses a symbol, not a USB-C photo")
        let adapterPower = PowerSnapshot(["ExternalConnected": true, "IsCharging": false, "PowerTelemetryData": ["SystemPowerIn": 33992], "AdapterDetails": ["Name": "35W USB-C Power Adapter", "Manufacturer": "Apple Inc.", "Watts": 35]])
        let related = RelatedCharger.reported(adapterPower)
        precondition(related?.name == "35W USB-C Power Adapter" && related?.power == "35 W" && related?.charging == false, "Related charger name, rating and charging state")
        precondition(related?.facts.contains(CableFact(name: "Mac power input", value: "34.0 W")) == true && RelatedCharger.reported(PowerSnapshot([:])) == nil, "Charger shows measured input and is absent without an adapter")
        let fixture = Model(fixture: "other-ports")
        precondition(fixture.items.count == 4 && fixture.items[0].charger != nil && fixture.items.dropFirst().allSatisfy { $0.charger == nil }, "The charger belongs to its cable, not to a separate list row")
        precondition(fixture.items[1].appleEMarker && !fixture.items[0].appleEMarker && fixture.items[0].charger?.apple == true, "Apple badge follows the reported e-marker vendor ID and adapter manufacturer")
        precondition(fixture.items[0].powering == true && fixture.items[1].powering == nil, "Only the powering connection gets the bolt tag")
        print("PASS: related charger identity, Apple badge, power tag, symbol fallback for HDMI and headphones, charger stays out of the list")
        let docks = Model(fixture: "dock")
        precondition(docks.items[0].dock?.title == "CalDigit TS4" && docks.items[0].dock?.devices.count == 5, "Thunderbolt dock keeps its reported maker, model and devices")
        precondition(docks.items.first { $0.id == "Port-USB-C@2" }?.dock?.title == "USB-C hub" && DockInfo(kind: "dock").title == "Thunderbolt dock", "Unnamed hubs and docks never get a guessed brand")
        precondition(ConnectionPhoto.name(kind: "dock", dark: true) == "hub-dark" && ConnectionPhoto.name(kind: "dock") == "hub-light" && ConnectionPhoto.name(kind: "hub") == "hub-light" && ConnectionPhoto.name(kind: "headphones", dark: true) == "headphones-dark" && ConnectionPhoto.name(kind: "keyboard") == "keyboard-light" && ConnectionPhoto.name(kind: "mouse", dark: true) == "mouse-dark" && ConnectionPhoto.name(kind: "storage") == nil, "Docks show the hub image; hubs, headphones, keyboards and mice switch with the appearance; other devices use symbols")
        precondition(docks.items.map(\.id) == ["Port-USB-C@1", "device:Port-USB-C@1:SteelSeries Arctis 5", "device:Port-USB-C@1:MINI60HE MAX", "device:Port-USB-C@1:Pulsar X2 v3", "ethernet:en6", "Port-USB-C@2"], "Cables behind a dock follow it in list and arrow-key order")
        precondition(docks.parent(of: docks.items.first { $0.id == "ethernet:en6" }!)?.id == "Port-USB-C@1" && docks.parent(of: docks.items[0]) == nil, "An Ethernet adapter inside a dock nests under it")
        precondition(Setting.bits(125_000) == "1.0 Mbit/s" && Setting.bits(100) == "800 bit/s" && Setting.bits(250_000_000) == "2.0 Gbit/s", "Bit rates convert bytes per second")
        let defaults = UserDefaults.standard, savedInterval = defaults.object(forKey: Setting.networkInterval), savedNesting = defaults.object(forKey: Setting.dockNesting)
        defaults.set(7.0, forKey: Setting.networkInterval)
        precondition(Setting.refreshInterval == 3, "Unknown refresh intervals fall back to 3 seconds")
        defaults.set(false, forKey: Setting.dockNesting)
        precondition(docks.parent(of: docks.items.first { $0.id == "ethernet:en6" }!) == nil, "Turning off dock nesting lists Ethernet on its own")
        defaults.set(savedInterval, forKey: Setting.networkInterval); defaults.set(savedNesting, forKey: Setting.dockNesting)
        print("PASS: settings: bit rates, refresh interval fallback, dock nesting switch")
        let children = docks.children(of: docks.items[0])
        precondition(children.map(\.kind) == ["headphones", "keyboard", "mouse", "ethernet"], "Headphones, keyboards, mice and the Ethernet adapter nest under a dock; storage does not")
        precondition(children[1].parent == "Port-USB-C@1" && children[1].chip == "Keyboard" && children[1].facts?.first?.value == "CalDigit TS4" && children[1].facts?.contains(CableFact(name: "USB link", value: "480 Mbps")) == true, "A keyboard behind a dock gets its own item naming the dock")
        precondition(ConnectionItem.device(DockDevice(name: "Pulsar X2", value: "12 Mbps · Pulsar", kind: "mouse"), through: docks.items[0])?.kind == "mouse" && ConnectionItem.device(DockDevice(name: "Drive", value: "5 Gbps", kind: "storage"), through: docks.items[0]) == nil, "Mice get items; storage stays in the hub detail")
        precondition(UsageMonitor.wireless("Logitech USB Receiver") && UsageMonitor.wireless("Pulsar 8K Dongle") && UsageMonitor.wireless("Arctis Nova 7 Wireless") && !UsageMonitor.wireless("MINI60HE MAX"), "Wireless receivers are recognised by name")
        precondition(DockDevice(name: "Pulsar 8K Dongle", value: "12 Mbps", kind: "mouse", wireless: true).shown?.label == "Wireless mouse" && DockDevice(name: "Arctis Nova 7", value: "", kind: "audio", wireless: true).shown?.kind == "headphones", "Wireless devices keep their category with a wireless tag")
        let receiver = ConnectionItem.device(DockDevice(name: "USB Receiver", value: "12 Mbps · Logitech", kind: "receiver", wireless: true), through: docks.items[0])
        precondition(receiver?.kind == "receiver" && receiver?.chip == "Receiver" && receiver?.facts?.contains(CableFact(name: "Connection", value: "Wireless USB receiver")) == true, "A receiver for both mouse and keyboard is shown as a receiver")
        print("PASS: wireless receivers for mice, keyboards and headsets are identified and tagged")
        print("PASS: dock and hub naming from reported maker and model, no guessed brands, docks shown with the light and dark hub image")
        precondition(PanelLayout.listHeight(count: 0) == 0)
        precondition(PanelLayout.listHeight(count: 1) == 96)
        precondition(PanelLayout.listHeight(count: 2) == 196)
        precondition(PanelLayout.listHeight(count: 10) == 320)
        let empty = Model(fixture: "empty")
        precondition(empty.items.isEmpty && empty.selected == nil)
        empty.moveSelection(1)
        precondition(empty.selected == nil)
        let pair = Model(fixture: "charger-cable")
        precondition(pair.items.count == 2 && pair.item?.name == "96 W charger")
        pair.moveSelection(1)
        precondition(pair.item?.speed == "40 Gbps")
        pair.moveSelection(10)
        precondition(pair.item?.name == "USB-C cable")
        pair.moveSelection(-10)
        precondition(pair.item?.name == "96 W charger")
        let limited = Model(fixture: "limited")
        precondition(limited.item?.tone == "amber" && limited.item?.power == "60 W")
        precondition(limited.item?.summary?.contains("96 W") == true)
        let unknown = Model(fixture: "no-emarker")
        precondition(unknown.items.count == 1 && unknown.item?.speed == nil && unknown.item?.power == nil && unknown.item?.verdict == nil)
        let ports = Parser.ports([["PortTypeDescription": "USB-C", "PortNumber": 1, "ConnectionActive": true, "TransportsActive": ["USB2"]], ["PortTypeDescription": "USB-C", "PortNumber": 2, "ConnectionActive": false]])
        let items = ports.filter { $0.connected == true }.map { ConnectionItem.live($0) }
        precondition(items.count == 1 && items[0].speed == nil && items[0].power == nil && items[0].chip == "Connected")
        precondition(items[0].accessibility.contains("USB-C cable"))
        let named = ConnectionItem.live(ports[0], metadata: ConnectionMetadata(name: "PSSD T5 EVO", facts: [CableFact(name: "PSSD T5 EVO · USB link", value: "5 Gbps")]))
        precondition(named.name == "PSSD T5 EVO" && named.speed == nil)
        precondition(named.facts?.contains { $0.name.hasSuffix(" · USB link") && $0.value == "5 Gbps" } == true)
        precondition(named.details.contains("PSSD T5 EVO · USB link: 5 Gbps"))
        precondition(StorageUsage.rate(2000, previous: 1000, elapsed: 2) == 500)
        precondition(StorageUsage.rate(1000, previous: 1000, elapsed: 2) == 0)
        precondition(StorageUsage.rate(500, previous: 1000, elapsed: 2) == nil)
        precondition(StorageUsage.rate(1000, previous: 500, elapsed: 0) == nil)
        precondition(StorageUsage.formatted(nil) == "—")
        precondition(StorageUsage.formatted(2_000_000) == "2.0 MB/s")
        var history = UsageHistory()
        history.append(0, at: 1)
        history.append(nil, at: 2)
        history.append(10, at: 3)
        precondition(history.points.count == 2 && history.points.first?.segment != history.points.last?.segment)
        history.append(20, at: 125)
        precondition(history.points.count == 1)
        for i in 0..<100 { history.append(Double(i), at: Double(i + 126)) }
        precondition(history.points.count <= 60)
        let field = DetailField("Selected power option: 9 V · 2.22 A · 19.98 W")
        precondition(field.name == "Selected power option" && field.value == "9 V · 2.22 A · 19.98 W")
        precondition(DetailField("Raw: value: with colon").value == "value: with colon")
        var hoverHistory = UsageHistory()
        precondition(hoverHistory.sample(near: 0) == nil)
        hoverHistory.append(0, at: 10)
        hoverHistory.append(100, at: 12)
        hoverHistory.append(nil, at: 14)
        hoverHistory.append(200, at: 22)
        precondition(hoverHistory.sample(near: 10)?.value == 0)
        precondition(hoverHistory.sample(near: 11.5)?.value == 100)
        precondition(hoverHistory.sample(near: 17) == nil)
        precondition(hoverHistory.sample(near: 9) == nil && hoverHistory.sample(near: 23) == nil)
        print("PASS: graph hover selects measured samples, preserves zero and leaves missing ranges empty")
        let fixtureRoot = URL(fileURLWithPath: FileManager.default.currentDirectoryPath).appendingPathComponent("Fixtures")
        let pdPorts = Parser.ports(try! Parser.load(Data(contentsOf: fixtureRoot.appendingPathComponent("ports-pd-recorded.plist"))))
        let pdItem = ConnectionItem.live(pdPorts.first { !$0.capabilities.profiles.isEmpty }!)
        precondition(pdItem.power == "19.98 W" && pdItem.profiles?.filter(\.active).count == 1)
        precondition(pdItem.speed == nil)
        let sourcePower = PowerSnapshot(["ExternalConnected": true, "PowerTelemetryData": ["SystemPowerIn": 51040]])
        let winningPorts = pdPorts.filter { $0.connected == true && $0.capabilities.active != nil }
        precondition(!winningPorts.isEmpty)
        let winner = winningPorts[0]
        precondition(GraphRouting.powerPortID(ports: [winner], power: sourcePower) == winner.id)
        precondition(GraphRouting.powerPortID(ports: [winner, winner], power: sourcePower) == nil)
        precondition(GraphRouting.powerPortID(ports: [], power: sourcePower) == nil)
        precondition(GraphRouting.powerPortID(ports: [winner], power: PowerSnapshot([:])) == nil)
        let scoped = [StorageUsage(id: 10, name: "SSD", readRate: 1, writeRate: 0, portID: "ssd-port"), StorageUsage(id: 11, name: "Unknown", readRate: 1, writeRate: 1)]
        precondition(GraphRouting.storage(scoped, portID: "ssd-port").map(\.id) == [10])
        precondition(GraphRouting.storage(scoped, portID: "monitor-port").isEmpty)
        let routing = Model(fixture: "graph-routing")
        precondition(routing.items.count == 2 && routing.powerGraphPortID == routing.items[0].id)
        precondition(GraphRouting.storage(routing.storageUsage, portID: routing.items[0].id).isEmpty)
        precondition(GraphRouting.storage(routing.storageUsage, portID: routing.items[1].id).count == 1)
        print("PASS: SSD and monitor graph isolation; unknown storage and ambiguous or disconnected power sources stay hidden")
        let telemetry = Model(fixture: "telemetry")
        precondition(telemetry.powerHistory.points.count == 60 && telemetry.readHistories[1]?.points.count == 60)
        precondition(telemetry.item?.profiles?.filter(\.active).count == 1)
        print("PASS: graph retention, missing-sample gaps, measured zero, fixture histories and active profile")
        for device in UsageMonitor.usbStorage() { print("LIVE USB storage: \(device.name), physical port: \(device.portID ?? "unresolved")") }
        for (id, metadata) in UsageMonitor.connectionDetails().sorted(by: { $0.key < $1.key }) {
            print("LIVE device: \(id), \(metadata.name ?? "name unavailable"), \(metadata.facts.map { $0.name + ": " + $0.value }.joined(separator: "; "))")
            if let dock = metadata.dock { print("LIVE \(dock.kind): \(id), \(dock.title), link \(dock.link ?? "-"), devices: \(dock.devices.map { "\($0.name) [\($0.kind ?? "other")]" }.joined(separator: ", ")), built in: \(dock.builtIn?.joined(separator: ", ") ?? "-")") }
        }
        print("PASS: monitoring rate calculations, idle versus unavailable, reset handling and formatting")
        print("PASS: all four UI fixtures, selection and arrow bounds, hidden empty ports, missing stats, no inferred cable ratings, spoken connection label")
        NSApp.terminate(nil)
    }
}
